class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        mx = max(groups)
        best = [-1] * (mx + 1)
        seen = set()
        for j, e in enumerate(elements):
            if e in seen or e > mx:
                continue
            seen.add(e)
            for m in range(e, mx + 1, e):
                if best[m] == -1:
                    best[m] = j
        return [best[g] for g in groups]

