class Solution {
    public int[] assignElements(int[] groups, int[] elements) {
        int mx = 0;
        for (int g : groups) mx = Math.max(mx, g);
        int[] best = new int[mx + 1];
        Arrays.fill(best, -1);
        boolean[] seen = new boolean[mx + 1];
        for (int j = 0; j < elements.length; j++) {
            int e = elements[j];
            if (e > mx || seen[e]) continue;
            seen[e] = true;
            for (int m = e; m <= mx; m += e)
                if (best[m] == -1) best[m] = j;
        }
        int[] res = new int[groups.length];
        for (int i = 0; i < groups.length; i++) res[i] = best[groups[i]];
        return res;
    }
}

