class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        first = {}
        for j, e in enumerate(elements):
            first.setdefault(e, j)
        res = []
        for g in groups:
            ans = -1
            d = 1
            while d * d <= g:
                if g % d == 0:
                    for dd in (d, g // d):
                        if dd in first and (ans == -1 or first[dd] < ans):
                            ans = first[dd]
                d += 1
            res.append(ans)
        return res

