class Solution {
public:
    vector<int> assignElements(vector<int>& groups, vector<int>& elements) {
        unordered_map<int,int> first;
        for (int j = 0; j < (int)elements.size(); j++)
            first.emplace(elements[j], j);
        vector<int> res;
        for (int g : groups) {
            int ans = -1;
            for (int d = 1; (long long)d * d <= g; d++)
                if (g % d == 0) {
                    int cands[2] = {d, g / d};
                    for (int dd : cands) {
                        auto it = first.find(dd);
                        if (it != first.end() && (ans == -1 || it->second < ans)) ans = it->second;
                    }
                }
            res.push_back(ans);
        }
        return res;
    }
};

