class Solution {
    public int[] assignElements(int[] groups, int[] elements) {
        Map<Integer, Integer> first = new HashMap<>();
        for (int j = 0; j < elements.length; j++) first.putIfAbsent(elements[j], j);
        int[] res = new int[groups.length];
        for (int i = 0; i < groups.length; i++) {
            int g = groups[i], ans = -1;
            for (int d = 1; (long) d * d <= g; d++)
                if (g % d == 0) {
                    int[] cands = {d, g / d};
                    for (int dd : cands) {
                        Integer j = first.get(dd);
                        if (j != null && (ans == -1 || j < ans)) ans = j;
                    }
                }
            res[i] = ans;
        }
        return res;
    }
}

